import unittest
from collector import score
from editor import edit
HEADLINES=["Bitcoin whales pile into BTC despite shrinking profit cushion","'It's impossible': Spain's young people on housing ahead of Sunday's election","Will new energy fixes cost more in January?","Bitcoin price drops below $59K as Anthropic joins tech stock rebound","A clinic is reassessing people with ADHD and autism diagnoses - but critics fear it could deepen stigma","My self-care ritual is a meal at a fancy restaurant - on my own","Bitcoin supply metric hits 11-year low as new ‘capitulation’ signal arrives","Behind China's spectacular rise, voices who defied it say they are being drowned out","'We're scared to turn our heating on'","Ethereum devs set Glamsterdam’s Hoodi rollout for mid-December after delays","Prosecutors seek 25-year prison term for 'poison seller' Kenneth Law","How much is your rent in Birmingham?","Binance to launch tokenized IPO program after regulatory approval: Yi He","Spanish PM and rivals rally supporters in final pitch for votes","The food bank helping pet owners with rising bills","Brazil’s stock exchange pushes stablecoin launch back to 2027","Capsized tanker carrying 7,000 tonnes of diesel to be towed away from Ibiza","From £250 job to £9,000 bill: Inside the rogue trader networks scamming customers at scale","Here’s what happened in crypto today","'We couldn't give up that easily': Marching bands scramble to cover costs after Thanksgiving parade rearranged","Franklin Templeton makes room for HYPE in crypto index ETF","Weary of war but with no sign of backing down, Kyiv faces another punishing winter","China sets March 2027 rollout for blockchain identity regulations","Zelensky criticises 'strange' Trump-Putin friendship in BBC interview","What was Coinbase worth while Nasdaq was closed?","Kenyan doomsday cult leader convicted over further 123 deaths","Austria-supervised crypto firms report 20.4B euros in H1 trading volume","Canada's top court largely upholds Quebec ban on religious symbols for public servants","Bluefin to shut down perps, refocus on spot trading and tokenized RWAs","Severe Thanksgiving storms leave roads flooded and trees fallen"]
class EditorialRegression(unittest.TestCase):
    def test_replay(self):
        self.assertEqual(len(HEADLINES),30)
        self.assertEqual([score({"title":t}) for t in HEADLINES],[45,40,20,70,20,0,45,20,20,70,20,20,95,55,20,60,20,20,20,20,20,55,80,20,20,20,20,55,20,20])
    def test_bad_translation(self):
        self.assertIsNone(edit({"title":"Stablecoin launch","source":"test","url":"https://example.org"},None,lambda _: "Запуск конюшни"))
